create role anon; create role authenticated; create role service_role;
create schema auth;
create function auth.role() returns text language sql stable as $$select coalesce(current_setting('request.jwt.claim.role',true),'service_role')$$;
create function public.has_business_role(uuid,text[]) returns boolean language sql stable as $$select coalesce(current_setting('test.business_id',true),'')=$1::text and coalesce(current_setting('test.manager',true),'')='true'$$;
create table public.businesses(id uuid primary key);
create table public.inventory_items(id uuid primary key,business_id uuid references businesses, name text default 'Rental',daily_price_cents integer,active boolean default true,allow_quantity boolean default true,stock_quantity integer default 10,standard_rental_hours_override integer,allow_multi_day_override boolean,additional_day_pricing_type_override text,additional_day_discount_percent_override numeric,additional_day_flat_rate_cents_override integer,max_rental_days_override integer);
create table public.booking_settings(business_id uuid,timezone text default 'America/Phoenix',buffer_minutes integer default 60,standard_rental_hours integer default 24,allow_multi_day_rentals boolean default true,additional_day_pricing_type text default 'percentage_discount',additional_day_discount_percent numeric default 25,additional_day_flat_rate_cents integer,max_rental_days integer);
create table public.customers(id uuid primary key default gen_random_uuid(),business_id uuid,first_name text,last_name text,email text,phone text,is_deleted boolean default false,updated_at timestamptz);
create unique index customer_email on customers(business_id,(lower(email))) where email is not null and btrim(email)<>'' and is_deleted=false;
create table public.bookings(id uuid primary key default gen_random_uuid(),business_id uuid,customer_id uuid,job_id uuid,booking_number bigint generated always as identity,status text,event_start_time time,event_end_time time,rental_starts_at timestamptz,rental_ends_at timestamptz,delivery_address text,delivery_city text,delivery_state text,delivery_zip text,notes text,subtotal_cents integer,tax_cents integer default 0,total_cents integer,agreement_accepted_at timestamptz,discount_cents integer default 0,discount_snapshot jsonb,delivery_fee_cents integer default 0,amount_paid_cents integer default 0,balance_due_cents integer,updated_at timestamptz);
create table public.booking_items(id uuid primary key default gen_random_uuid(),booking_id uuid,inventory_item_id uuid,rental_date date,quantity integer,unit_price_cents integer,status text,rental_days integer,base_unit_price_cents integer,additional_day_unit_price_cents integer,rental_pricing_type text,standard_rental_hours integer,option_selections jsonb,option_adjustment_cents integer default 0,standard_rental_hours_snapshot integer,duration_adjustment_cents integer default 0,operator_charge_cents integer default 0,created_at timestamptz default now());
create table public.rental_listing_inventory_requirements(listing_inventory_item_id uuid,resource_inventory_item_id uuid,quantity_required integer);
create table public.blocked_dates(inventory_item_id uuid,blocked_date date);
create table public.booking_inventory_reservations(business_id uuid,booking_id uuid,booking_item_id uuid,listing_inventory_item_id uuid,resource_inventory_item_id uuid,quantity integer,revenue_allocation_weight numeric,rental_starts_at timestamptz,rental_ends_at timestamptz);
create table public.booking_amendments(id uuid primary key,business_id uuid,booking_id uuid,status text,expires_at timestamptz,requested_items jsonb,pricing_snapshot jsonb,old_totals jsonb,new_totals jsonb);
create table public.booking_amendment_inventory_holds(resource_inventory_item_id uuid,amendment_id uuid,quantity integer,rental_starts_at timestamptz,rental_ends_at timestamptz);
create table public.inventory_item_booking_options(id uuid,inventory_item_id uuid,required boolean,name text,sort_order integer);
create table public.inventory_item_booking_option_choices(id uuid,option_id uuid,label text,price_adjustment_cents integer,sort_order integer);
create table public.jobs(id uuid,business_id uuid,subtotal numeric,tax_amount numeric,discount_amount numeric,description text,updated_at timestamptz);
create table public.booking_change_audit(booking_id uuid,business_id uuid,change_source text,change_type text,old_values jsonb,new_values jsonb,resulting_total_cents integer,resulting_balance_due_cents integer, constraint booking_change_audit_change_source_check check(true));
